import{_ as t,o as e,c as r,a3 as d}from"./chunks/framework.D8u9WiMi.js";const i="/SumUP/assets/cc4b484215cd20dae8843729ec7ba566.dN0JsdHm.png",o="/SumUP/assets/35ae3b4e8209a15f80d95b6d61d4aef6.PJxVh0LV.png",s="/SumUP/assets/b74e9783789e791d1e53427af4484d26.BAG4ffpq.png",c="/SumUP/assets/bcd10db61407fad87d8dc504a554a6e8.erDNeKAr.png",l="/SumUP/assets/636d51bee52d7eb3aa6c6486e635cf48.C2ozBAmM.png",n="/SumUP/assets/0ac0272a50f87b2d888625c1f9ed03eb.DViqWvfK.png",p="/SumUP/assets/210148aa135b1cbf048fe8dd268aa4d3._3KNHgb0.png",S=JSON.parse('{"title":"知识加油站","description":"","frontmatter":{},"headers":[],"relativePath":"server/java/basic/advanced1/supplement.md","filePath":"server/java/basic/advanced1/supplement.md"}'),u={name:"server/java/basic/advanced1/supplement.md"};function b(m,a,f,h,g,_){return e(),r("div",null,[...a[0]||(a[0]=[d('<h1 id="知识加油站" tabindex="-1">知识加油站 <a class="header-anchor" href="#知识加油站" aria-label="Permalink to &quot;知识加油站&quot;">​</a></h1><h2 id="idea中查看此方法的源码" tabindex="-1">IDEA中查看此方法的源码 <a class="header-anchor" href="#idea中查看此方法的源码" aria-label="Permalink to &quot;IDEA中查看此方法的源码&quot;">​</a></h2><p>若IDEA中进行Ctrl+B查看的是此方法的接口</p><p><img src="'+i+'" alt="image-20230425111615513"></p><p>那么我们可以选中方法，进行实现方法的查看。</p><p><img src="'+o+'" alt="image-20230425111652280"></p><h2 id="idea中包裹代码快捷键" tabindex="-1">IDEA中包裹代码快捷键 <a class="header-anchor" href="#idea中包裹代码快捷键" aria-label="Permalink to &quot;IDEA中包裹代码快捷键&quot;">​</a></h2><p>若IDEA中使用Ctrl+Alt+T快捷键，可选择操作项进行包裹代码</p><p><img src="'+s+'" alt="image-20230426114136309"></p><h2 id="idea中提取代码快捷键" tabindex="-1">IDEA中提取代码快捷键 <a class="header-anchor" href="#idea中提取代码快捷键" aria-label="Permalink to &quot;IDEA中提取代码快捷键&quot;">​</a></h2><p><strong>Ctrl + Alt + M</strong></p><p><img src="'+c+'" alt="image-20230429114159940"></p><h2 id="java中异常处理的扩展方式" tabindex="-1">Java中异常处理的扩展方式 <a class="header-anchor" href="#java中异常处理的扩展方式" aria-label="Permalink to &quot;Java中异常处理的扩展方式&quot;">​</a></h2><p><img src="'+l+'" alt="image-20230427091534645"></p><h2 id="stringbuilder和stringbuffer区别" tabindex="-1">StringBuilder和StringBuffer区别 <a class="header-anchor" href="#stringbuilder和stringbuffer区别" aria-label="Permalink to &quot;StringBuilder和StringBuffer区别&quot;">​</a></h2><p><img src="'+n+'" alt="image-20230429111344077"></p><p><img src="'+p+'" alt="image-20230429111407230"></p><div class="tip custom-block"><p class="custom-block-title">说明</p><p><code>StringBuilder</code>和<code>StringBuffer</code>在java中的方法都是一样的，区别就在于，<code>StringBuffer</code>为每个方法添加了同步方法，这样在操作方法时，保证只有一个方法来操作，从而提升了代码安全性</p></div><blockquote><p>若只是单线程，则使用<code>StringBuilder即可，若是在多线程环境下，需要考虑线程安全，则使用StringBuffer</code></p></blockquote><h2 id="arrays数组工具类" tabindex="-1">Arrays数组工具类 <a class="header-anchor" href="#arrays数组工具类" aria-label="Permalink to &quot;Arrays数组工具类&quot;">​</a></h2><p><strong>操作数组的工具类</strong></p><table tabindex="0"><thead><tr><th>方法名</th><th>说明</th></tr></thead><tbody><tr><td><code>public static String toString(数组)</code></td><td>把数组拼接成一个字符串</td></tr><tr><td><code>public static int binarySearch(数组，查找的元素)</code></td><td>二分查找法查找元素</td></tr><tr><td><code>public static int[] copyOf(原数组，新数组长度)</code></td><td>拷贝数组</td></tr><tr><td><code>publci static int[] copyOfRange(原数组，起始索引，结束索引)</code></td><td>拷贝数组（指定范围）</td></tr><tr><td><code>public static void fill(数组，元素)</code></td><td>填充数组</td></tr><tr><td><code>public static void sort(数组)</code></td><td>按照默认方式进行数组排序</td></tr><tr><td><code>public static void sort(数组，排序规则)</code></td><td>按照指定的规则排序</td></tr></tbody></table><p>在Java中，<code>Arrays</code>是一个提供了许多有用的静态方法的类，可以用于操作和处理数组。</p><p>以下是<code>Arrays</code>类的一个常见用法：</p><ol><li><code>Arrays.fill()</code>方法：用于将数组的所有元素设置为指定的值。</li><li><code>Arrays.equals()</code>方法：用于比较两个数组是否相等。</li><li><code>Arrays.asList()</code>方法：用于将数组转换为列表。</li></ol><p>需要注意的是，<code>Arrays</code>类的大多数方法都是静态方法，因此不需要创建<code>Arrays</code>对象就可以调用它们。另外，<code>Arrays</code>类中的方法适用于所有基本数据类型的数组，已经对象数组。</p>',26)])])}const v=t(u,[["render",b]]);export{S as __pageData,v as default};
